script:
//Issue - ISS-2024-02909
frappe.ui.form.on("Task", {
    refresh (frm) {
        // If this task is a virtual task linked to an Issue, redirect to that Issue
        if (frm.doc.type == "Issue" && frm.doc.custom_linked_issue) {
            //Очистить историю браузера
            history.replaceState(null, null, frappe.router.make_url( frappe.get_prev_route() ) );
            //Перенаправляем пользователя
            frappe.set_route("Form", "Issue", frm.doc.custom_linked_issue);
        }
    }
});
